package dev.jackteng.encore;

import com.fasterxml.jackson.databind.ObjectMapper;
import dev.jackteng.encore.admission.AdmissionSettings;
import dev.jackteng.encore.catalog.*;
import dev.jackteng.encore.catalog.Models.*;
import dev.jackteng.encore.common.ApiErrors.Problem;
import dev.jackteng.encore.customer.CustomerService;
import dev.jackteng.encore.inventory.*;
import dev.jackteng.encore.inventory.RedisTicketLedger.*;
import dev.jackteng.encore.inventory.StockHoldService.*;
import dev.jackteng.encore.orders.*;
import dev.jackteng.encore.orders.OrderModels.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.admission.enabled=false","ticket.orders.enabled=true","ticket.purchases.enabled=true","ticket.mock-payments.enabled=true","ticket.expiry.enabled=false"})
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class StockHoldIntegrationTest {
 @Autowired StockHoldService holds;@Autowired StockProjectionService projections;@Autowired JdbcTemplate db;@Autowired StringRedisTemplate redis;@Autowired ObjectMapper json;@Autowired AdmissionSettings settings;
 @Autowired CatalogService catalog;@Autowired CustomerService customers;@Autowired OrderService orders;@Autowired PurchaseService purchases;@Autowired PlatformTransactionManager transactions;
 RedisTicketLedger ledger;final Set<String> keys=new HashSet<>();String manager="hold-"+UUID.randomUUID();
 @BeforeAll void seed(){assertEquals("ticket_demo",db.queryForObject("SELECT current_database()",String.class));ledger=RedisTicketLedger.epochs(redis,json,settings.namespace());db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),manager,"unused synthetic hash","MANAGER");}
 @AfterEach void cleanup(){redis.delete(keys);keys.clear();}
 UUID ticket(){return ticket(7200);}
 UUID ticket(int seconds){var e=catalog.createEvent(manager,new EventInput(UUID.randomUUID(),0L,"hold-"+UUID.randomUUID(),"預扣合成","不售票","隔離"));var now=OffsetDateTime.now();var s=catalog.createSession(manager,e.id(),new SessionInput(UUID.randomUUID(),0L,"合成",now.plusDays(2),now.minusHours(1),now.plusSeconds(seconds)));var t=catalog.createTicket(manager,s.id(),new TicketInput(UUID.randomUUID(),0L,"一般",1200,4,4));catalog.transition(manager,e.id(),new Transition(UUID.randomUUID(),1L),true);ready(t.id());return t.id();}
 void ready(UUID t){var c=projections.begin(t,UUID.randomUUID(),projections.inspect(t).sourceRevision());keys.add(ledger.key(t,c.generation()));assertEquals("READY",projections.complete(c.requestId()).state());}
 CustomerService.Principal customer(){var c=customers.register("hi-"+UUID.randomUUID().toString().substring(0,30),"合成",UUID.randomUUID().toString());return customers.authenticate(c.token()).orElseThrow();}
 Place place(UUID t){return new Place(UUID.randomUUID(),t,1,1,1200);}
 Intent intent(UUID t){return holds.prepare(customer(),place(t));}
 Claim claim(Intent c){return new Claim(c.generation(),c.id(),c.owner(),c.quantity(),c.deadlineAt().toInstant().toEpochMilli(),db.queryForObject("SELECT claim_fingerprint FROM stock_hold_intent WHERE id=?",String.class,c.id()));}
 void problem(String code,Runnable op){assertEquals(code,assertThrows(Problem.class,op::run).code);}
 void cleanPg(Intent c){assertEquals(0,db.queryForObject("SELECT held FROM ticket_type WHERE id=?",Integer.class,c.ticketId()));assertEquals(0,db.queryForObject("SELECT count(*) FROM ticket_order WHERE customer_id=?",Integer.class,c.owner()));}
 void active(UUID t){problem("ACTIVE_STOCK_INTENTS",()->projections.begin(t,UUID.randomUUID(),projections.inspect(t).sourceRevision()));}

 @Test void committedVerifiedIntentPrecedesLuaAndDoesNotReserveFormalStock(){var t=ticket();var c=intent(t);assertEquals("PREPARED",holds.inspect(c.id()).state());assertEquals(Code.MISSING,ledger.lookup(t,claim(c)).code());assertEquals(4,ledger.snapshot(t,1).snapshot().available());cleanPg(c);assertEquals("HELD",holds.apply(c.id()).state());assertEquals(3,ledger.snapshot(t,1).snapshot().available());cleanPg(c);}
 @Test void sixConcurrentOriginalRetriesCreateOneIntentAndOneReceipt()throws Exception{var t=ticket();var p=customer();var body=place(t);Intent c;try(var pool=Executors.newFixedThreadPool(6)){var tasks=new ArrayList<Callable<Intent>>();for(int i=0;i<6;i++)tasks.add(()->holds.prepare(p,body));var results=pool.invokeAll(tasks);c=results.getFirst().get();for(var r:results)assertEquals(c,r.get());var apply=new ArrayList<Callable<Attempt>>();for(int i=0;i<6;i++)apply.add(()->holds.apply(results.getFirst().get().id()));for(var r:pool.invokeAll(apply))assertEquals("HELD",r.get().state());}assertEquals(1,db.queryForObject("SELECT count(*) FROM stock_hold_intent WHERE customer_id=?",Integer.class,p.id()));assertEquals(1,ledger.snapshot(t,1).snapshot().entries());assertEquals(3,ledger.snapshot(t,1).snapshot().available());}
 @Test void ownerScopedSameUuidUsesDifferentDurableLedgerIds(){var t=ticket();var b=place(t);var a=holds.prepare(customer(),b);var c=holds.prepare(customer(),b);assertNotEquals(a.id(),c.id());holds.apply(a.id());holds.apply(c.id());assertEquals(2,ledger.snapshot(t,1).snapshot().held());}
 @Test void changedOriginalBodyConflictsAndReplaySurvivesDirtyGate(){var t=ticket();var p=customer();var b=place(t);var c=holds.prepare(p,b);problem("REQUEST_CONFLICT",()->holds.prepare(p,new Place(b.requestId(),t,2,1,2400)));db.update("UPDATE ticket_type SET capacity=capacity+1 WHERE id=?",t);assertEquals(c,holds.prepare(p,b));assertEquals("STOCK_GATE_CLOSED",holds.apply(c.id()).failure());assertEquals(4,ledger.snapshot(t,1).snapshot().available());}
 @Test void stockAndSessionAreCheckedBeforeNewDebit(){var t=ticket();var p=customer();problem("QUOTE_CHANGED",()->holds.prepare(p,new Place(UUID.randomUUID(),t,1,1,1)));db.update("UPDATE customer_account SET enabled=false WHERE id=?",p.id());problem("UNAUTHENTICATED",()->holds.prepare(p,place(t)));assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_hold_intent WHERE customer_id=?",Integer.class,p.id()));}
 @Test void quotaIncludesUnresolvedIntentsAndFormalOrders(){var t=ticket();var p=customer();orders.place(p,new Place(UUID.randomUUID(),t,2,1,2400));ready(t);holds.prepare(p,new Place(UUID.randomUUID(),t,2,1,2400));problem("PURCHASE_LIMIT",()->holds.prepare(p,place(t)));}
 @Test void originalPreDebitCannotBeReusedByLegacyPurchaseOrOrder(){var t=ticket();var p=customer();var b=place(t);var c=holds.prepare(p,b);problem("REQUEST_CONFLICT",()->orders.place(p,b));problem("REQUEST_CONFLICT",()->purchases.submit(p,b));holds.abandon(c.id());problem("REQUEST_CONFLICT",()->orders.place(p,b));problem("REQUEST_CONFLICT",()->purchases.submit(p,b));}
 @Test void originalPurchaseAndOrderCannotBecomeAnIntent(){var t=ticket();var p=customer();var b=place(t);purchases.submit(p,b);problem("REQUEST_CONFLICT",()->holds.prepare(p,b));var other=place(t);orders.place(p,other);ready(t);problem("REQUEST_CONFLICT",()->holds.prepare(p,other));}
 @Test void pgIntentFailureIssuesNoLuaAndRollsBackProgress(){var t=ticket();var p=customer();var b=place(t);db.execute("ALTER TABLE stock_hold_progress ADD CONSTRAINT intent_insert_fault CHECK(false) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->holds.prepare(p,b));assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_hold_intent WHERE customer_id=?",Integer.class,p.id()));assertEquals(0,ledger.snapshot(t,1).snapshot().entries());}finally{db.execute("ALTER TABLE stock_hold_progress DROP CONSTRAINT intent_insert_fault");}assertNotNull(holds.prepare(p,b));}
 @Test void luaSuccessPgRollbackRecoversOriginalWithoutAnotherDebit(){var t=ticket();var c=intent(t);db.execute("ALTER TABLE stock_hold_progress ADD CONSTRAINT held_ack_fault CHECK(NOT(intent_id='"+c.id()+"'::uuid AND state='HELD')) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->holds.apply(c.id()));assertEquals("PREPARED",holds.inspect(c.id()).state());assertEquals(Status.HELD,ledger.lookup(t,claim(c)).receipt().status());active(t);}finally{db.execute("ALTER TABLE stock_hold_progress DROP CONSTRAINT held_ack_fault");}db.update("UPDATE customer_account SET enabled=false WHERE id=?",c.owner());assertEquals("HELD",holds.apply(c.id()).state());assertEquals(1,ledger.snapshot(t,1).snapshot().entries());assertEquals(3,ledger.snapshot(t,1).snapshot().available());cleanPg(c);}
 @Test void expiredDeadlineDoesNotAutomaticallyReturnStock()throws Exception{var t=ticket(2);var c=intent(t);holds.apply(c.id());while(OffsetDateTime.now().isBefore(c.deadlineAt()))Thread.sleep(20);assertEquals("HELD",holds.apply(c.id()).state());assertEquals(3,ledger.snapshot(t,1).snapshot().available());active(t);assertEquals("ABORTED",holds.abandon(c.id()).state());assertEquals(4,ledger.snapshot(t,1).snapshot().available());}
 @Test void revokedSessionPreventsFreshLuaButCanAbandonExistingIntent(){var t=ticket();var c=intent(t);db.update("UPDATE customer_account SET session_version=session_version+1 WHERE id=?",c.owner());assertEquals("UNAUTHENTICATED",holds.apply(c.id()).failure());assertEquals(0,ledger.snapshot(t,1).snapshot().entries());assertEquals("ABORTED",holds.abandon(c.id()).state());}
 @Test void activeIntentBlocksRebuildAndSameEpochReinitialization(){var t=ticket();var c=intent(t);active(t);var request=projections.inspect(t).rebuildRequestId();problem("STOCK_INTENTS_PRESENT",()->projections.complete(request));holds.apply(c.id());active(t);assertEquals(1,projections.inspect(t).generation());}
 @Test void abandonedReceiptIsTerminalAcrossNewGenerationAndOriginalReplay(){var t=ticket();var p=customer();var b=place(t);var c=holds.prepare(p,b);holds.apply(c.id());assertEquals("ABORTED",holds.abandon(c.id()).state());assertEquals(Status.RELEASED,ledger.lookup(t,claim(c)).receipt().status());assertEquals(Phase.FROZEN,ledger.snapshot(t,1).snapshot().phase());ready(t);assertEquals(2,projections.inspect(t).generation());assertEquals(c,holds.prepare(p,b));assertEquals("ABANDONED",holds.apply(c.id()).failure());assertEquals(0,ledger.snapshot(t,2).snapshot().entries());}
 @Test void noReceiptAbandonmentFreezesEpochBeforeDeclaringAbsence(){var t=ticket();var c=intent(t);assertEquals("ABORTED",holds.abandon(c.id()).state());assertEquals("ABSENT",db.queryForObject("SELECT resolution FROM stock_hold_progress WHERE intent_id=?",String.class,c.id()));assertEquals(Code.CLOSED,ledger.hold(t,claim(c)).code());assertEquals(Code.CLOSED,ledger.open(t,1).code());}
 @Test void abortDecisionPgFailureCannotFreezeOrReleaseRedis(){var t=ticket();var c=intent(t);holds.apply(c.id());db.execute("ALTER TABLE stock_hold_progress ADD CONSTRAINT abort_decision_fault CHECK(NOT(intent_id='"+c.id()+"'::uuid AND state='ABORTING')) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->holds.abandon(c.id()));assertEquals("HELD",holds.inspect(c.id()).state());assertEquals("READY",projections.inspect(t).state());assertEquals(Phase.OPEN,ledger.snapshot(t,1).snapshot().phase());assertEquals(Status.HELD,ledger.lookup(t,claim(c)).receipt().status());}finally{db.execute("ALTER TABLE stock_hold_progress DROP CONSTRAINT abort_decision_fault");}}
 @Test void releaseSuccessPgRollbackRetainsDecisionAndRetryDoesNotDoubleReturn(){var t=ticket();var c=intent(t);holds.apply(c.id());db.execute("ALTER TABLE stock_hold_progress ADD CONSTRAINT release_ack_fault CHECK(NOT(intent_id='"+c.id()+"'::uuid AND state='ABORTED')) NOT VALID");try{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->holds.abandon(c.id()));assertEquals("ABORTING",holds.inspect(c.id()).state());assertEquals("DIRTY",projections.inspect(t).state());assertEquals(Status.RELEASED,ledger.lookup(t,claim(c)).receipt().status());active(t);}finally{db.execute("ALTER TABLE stock_hold_progress DROP CONSTRAINT release_ack_fault");}assertEquals("ABORTED",holds.reconcileAbandonment(c.id()).state());holds.abandon(c.id());assertEquals(4,ledger.snapshot(t,1).snapshot().available());}
 @Test void missingEpochIsNeverReSeededAndRequiresDurableAbandonment(){var t=ticket();var c=intent(t);holds.apply(c.id());redis.delete(ledger.key(t,1));assertEquals("REDIS_MISSING",holds.apply(c.id()).failure());active(t);assertFalse(redis.hasKey(ledger.key(t,1)));assertEquals("ABORTED",holds.abandon(c.id()).state());assertEquals("KEY_MISSING",db.queryForObject("SELECT resolution FROM stock_hold_progress WHERE intent_id=?",String.class,c.id()));ready(t);assertFalse(redis.hasKey(ledger.key(t,1)));assertEquals(4,ledger.snapshot(t,2).snapshot().available());}
 @Test void corruptEpochLeavesAbortingAndBlocksNewGeneration(){var t=ticket();var c=intent(t);redis.delete(ledger.key(t,1));redis.opsForValue().set(ledger.key(t,1),"synthetic corrupt");assertEquals("REDIS_CORRUPT",holds.apply(c.id()).failure());assertEquals("REDIS_CORRUPT",holds.abandon(c.id()).failure());assertEquals("ABORTING",holds.inspect(c.id()).state());active(t);assertEquals("synthetic corrupt",redis.opsForValue().get(ledger.key(t,1)));}
 @Test void committedReceiptCannotBeMistakenForUnusedReleasedStock(){var t=ticket();var c=intent(t);holds.apply(c.id());ledger.commit(t,claim(c));assertEquals("REDIS_COMMITTED_REQUIRES_RECONCILIATION",holds.abandon(c.id()).failure());assertEquals("ABORTING",holds.inspect(c.id()).state());active(t);assertEquals(3,ledger.snapshot(t,1).snapshot().available());assertEquals(Status.COMMITTED,ledger.lookup(t,claim(c)).receipt().status());}
 @Test void concurrentHoldAndAbandonmentSerializeAndPreventLateWriter()throws Exception{var t=ticket();var c=intent(t);try(var pool=Executors.newFixedThreadPool(2)){for(var f:pool.invokeAll(List.<Callable<Attempt>>of(()->holds.apply(c.id()),()->holds.abandon(c.id()))))assertNotNull(f.get());}assertEquals("ABORTED",holds.inspect(c.id()).state());assertEquals("ABANDONED",holds.apply(c.id()).failure());assertEquals(4,ledger.snapshot(t,1).snapshot().available());assertEquals(Phase.FROZEN,ledger.snapshot(t,1).snapshot().phase());cleanPg(c);}
 @Test void allOutstandingIntentsMustResolveBeforeRebuild(){var t=ticket();var a=intent(t);var b=intent(t);holds.apply(a.id());holds.apply(b.id());holds.abandon(a.id());active(t);assertEquals("HELD",holds.apply(b.id()).state());holds.abandon(b.id());ready(t);assertEquals(4,ledger.snapshot(t,2).snapshot().available());}
 @Test void intentAndTerminalEvidenceCannotBeMutatedOrDeleted(){var t=ticket();var c=intent(t);for(String q:List.of("UPDATE stock_hold_intent SET quantity=quantity WHERE id=?","DELETE FROM stock_hold_intent WHERE id=?","DELETE FROM stock_hold_progress WHERE intent_id=?"))assertThrows(org.springframework.dao.DataAccessException.class,()->db.update(q,c.id()));problem("ABANDONMENT_NOT_DECIDED",()->holds.reconcileAbandonment(c.id()));holds.abandon(c.id());assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE stock_hold_progress SET state='PREPARED',abort_at=NULL,abort_reason=NULL,resolved_at=NULL,resolution=NULL WHERE intent_id=?",c.id()));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE stock_hold_progress SET abort_reason='CHANGED' WHERE intent_id=?",c.id()));}
 @Test void uncommittedOuterTransactionCannotHideEitherDurablePhase(){var t=ticket();var p=customer();var c=holds.prepare(p,place(t));new TransactionTemplate(transactions).execute(tx->{assertThrows(IllegalStateException.class,()->holds.prepare(p,place(t)));assertThrows(IllegalStateException.class,()->holds.apply(c.id()));assertThrows(IllegalStateException.class,()->holds.abandon(c.id()));assertThrows(IllegalStateException.class,()->holds.reconcileAbandonment(c.id()));return null;});assertEquals("PREPARED",holds.inspect(c.id()).state());assertEquals(0,ledger.snapshot(t,1).snapshot().entries());}
}
